export const ALL_ZONES: ZoneDef[] = [
  ...STATE_PLANE_ZONES,
  ...UTM_ZONES,
  GEOGRAPHIC_ZONE,
];

export function findZone(id: string): ZoneDef | undefined {
  return ALL_ZONES.find(z => z.id === id);
}

// ─── Horizontal datums ──────────────────────────────────────────────────────
// family 'nad83': computed on the NAD83 / GRS80 frame. Phone GPS is only good to
//   a few metres, so the realizations (and WGS 84 / ITRF, within ~1–2 m of
//   NAD83 in the US) are indistinguishable here — the choice labels the export.
// family 'nad27': converted with an approximate NAD27 shift (can be off by
//   several metres) and NAD27 zone constants.

export type HorizontalDatum = {
  id: string;
  label: string;
  short: string;
  family: 'nad83' | 'nad27';
};

