// ─── Units for Northing / Easting ───────────────────────────────────────────

export type CoordinateUnits = 'usft' | 'ift' | 'm';

export const UNIT_OPTIONS: {id: CoordinateUnits; label: string; short: string; perMetre: number}[] = [
  {id: 'usft', label: 'US survey feet', short: 'US ft', perMetre: 3937 / 1200},
  {id: 'ift', label: 'International feet', short: 'Intl ft', perMetre: 1 / 0.3048},
  {id: 'm', label: 'Meters', short: 'm', perMetre: 1},
];

// ─── A template's / job's coordinate settings ───────────────────────────────

export type CoordinateSystem = {
  zoneId: string;
  horizontalDatum: string;
  verticalDatum: string;
  units: CoordinateUnits;
};

export const SPIKE_COORDINATE_SYSTEM: CoordinateSystem = {
  zoneId: 'SPCS83-32122', // Ohio North (FIPS 3401)
  horizontalDatum: 'NAD83',
  verticalDatum: 'NAVD88',
  units: 'usft',
};

/** e.g. "OH North, NAD83 / NAVD88" */
export function describeCoordinateSystem(cs: CoordinateSystem): string {
  const zone = findZone(cs.zoneId)?.short ?? cs.zoneId;
  const h = HORIZONTAL_DATUMS.find(d => d.id === cs.horizontalDatum)?.short ?? cs.horizontalDatum;
  const v = VERTICAL_DATUMS.find(d => d.id === cs.verticalDatum)?.short ?? cs.verticalDatum;
  return `${zone}, ${h} / ${v}`;
}
